import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"HardwarePT — toolkit de pentest de hardware","description":"Toolkit de bajo nivel en C para sondeo y pentest de hardware — puertos, dispositivos, superficies de firmware y pruebas de estrés.","frontmatter":{"title":"HardwarePT — toolkit de pentest de hardware","description":"Toolkit de bajo nivel en C para sondeo y pentest de hardware — puertos, dispositivos, superficies de firmware y pruebas de estrés."},"headers":[],"relativePath":"es/projects/hardwarept/index.md","filePath":"es/projects/hardwarept/index.md"}`),a={name:`es/projects/hardwarept/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="hardwarept-—-toolkit-de-pentest-de-hardware" tabindex="-1">HardwarePT — toolkit de pentest de hardware <a class="header-anchor" href="#hardwarept-—-toolkit-de-pentest-de-hardware" aria-label="Permalink to “HardwarePT — toolkit de pentest de hardware”">​</a></h1><p><strong><a href="https://github.com/Godde3s/HardwarePT" target="_blank" rel="noreferrer">HardwarePT</a></strong> es mi proyecto de bajo nivel en C: un toolkit de sondeo y pentest centrado en hardware que habla con la máquina por debajo del sistema operativo. Nació de la misma curiosidad que me llevó a la automatización industrial — saber qué hace un dispositivo <em>antes</em> de fiarme de lo que dice.</p><h2 id="que-cubre" tabindex="-1">Qué cubre <a class="header-anchor" href="#que-cubre" aria-label="Permalink to “Qué cubre”">​</a></h2><ul><li><strong>Enumeración de hardware</strong> — buses, dispositivos e interfaces desde espacio de usuario.</li><li><strong>Sondeo de superficie de ataque</strong> — interfaces de depuración expuestas, configuraciones por defecto débiles y estados inseguros.</li><li><strong>Pruebas de estrés</strong> — generación controlada de carga para observar el comportamiento del firmware en los límites.</li><li><strong>C puro, sin frameworks</strong> — syscalls e interfaces directas: el código que te enseña qué hace tu tooling de verdad.</li></ul><p>Ocupa el carril de seguridad de mi portafolio junto a mis herramientas de análisis estático: entender sistemas desmontándolos — hardware esta vez — y anotar lo que encuentro de forma reutilizable.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};